from collections import Counter
from pathlib import Path

def _runs(vals, bg):
    runs=[]
    i=0
    while i<len(vals):
        if vals[i]==bg:
            i+=1; continue
        col=vals[i]; j=i+1
        while j<len(vals) and vals[j]==col: j+=1
        runs.append((col,i,j))
        i=j
    return runs

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    candidates=[]
    # edge-aligned bars: match same-color runs of equal length on opposite edges
    for orient in ('horizontal','vertical'):
        if orient=='horizontal':
            edge_a=[(c,s,e,'left') for c,s,e in _runs([g[r][0] for r in range(h)],bg)]
            edge_b=[(c,s,e,'right') for c,s,e in _runs([g[r][w-1] for r in range(h)],bg)]
        else:
            edge_a=[(c,s,e,'top') for c,s,e in _runs(g[0],bg)]
            edge_b=[(c,s,e,'bottom') for c,s,e in _runs(g[h-1],bg)]
        for ca,sa,ea,sidea in edge_a:
            for cb,sb,eb,sideb in edge_b:
                if ca==cb and ea-sa==eb-sb and ea-sa>=2:
                    candidates.append((ea-sa,orient,ca,(sa,ea,sidea),(sb,eb,sideb)))
    if not candidates:
        return g
    _,orient,bar_color,seg_a,seg_b=max(candidates)
    source_cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg and g[r][c]!=bar_color]
    if not source_cells:
        return g
    source_color=Counter(v for _,_,v in source_cells).most_common(1)[0][0]
    # Runs are in edge coordinate order; associate each source with a matching offset.
    selected=[]
    for r,c,col in source_cells:
        idx=r if orient=='horizontal' else c
        if seg_a[0] <= idx < seg_a[1]:
            selected.append((idx-seg_a[0],r,c,col,seg_a[2]))
        elif seg_b[0] <= idx < seg_b[1]:
            selected.append((idx-seg_b[0],r,c,col,seg_b[2]))
    for off,r,c,col,side in selected:
        # Extend the source toward its edge bar.
        if orient=='horizontal':
            if side=='left':
                for cc in range(1,c): g[r][cc]=source_color
            else:
                for cc in range(c+1,w-1): g[r][cc]=source_color
        else:
            if side=='top':
                for rr in range(1,r): g[rr][c]=source_color
            else:
                for rr in range(r+1,h-1): g[rr][c]=source_color
        g[r][c]=4
        # Extend from the corresponding location on the opposite edge.
        if side=='left':
            rr=seg_b[0]+off
            for cc in range(1,w): g[rr][cc]=source_color
        elif side=='right':
            rr=seg_a[0]+off
            for cc in range(0,w-1): g[rr][cc]=source_color
        elif side=='top':
            cc=seg_b[0]+off
            for rr in range(1,h): g[rr][cc]=source_color
        else: # bottom
            cc=seg_a[0]+off
            for rr in range(0,h-1): g[rr][cc]=source_color
    # Sources always remain marked in color 4, including any line overlaps.
    for r,c,col in source_cells:
        if col==source_color:
            g[r][c]=4
    return g

